sksl:
uniform shader image;
uniform float2 size;
uniform float4 screen;
uniform float time;
uniform float strength;
uniform float2 offset;
uniform float count;
uniform float2 stretch;
uniform float angle;
uniform float seed;
uniform float screenSpace;
uniform float edges;
uniform float style;
uniform float edgeStyle;
float hash12(float2 p) {
    float3 q = fract(float3(p.xyx) * 0.1031);
    q += dot(q, q.yzx + 33.33);
    return fract((q.x + q.y) * q.z);
}
float2 hash22(float2 p) {
    float3 q = fract(float3(p.xyx) * float3(0.1031, 0.1030, 0.0973));
    q += dot(q, q.yzx + 33.33);
    return fract((q.xx + q.yz) * q.zy);
}
half4 main(float2 coord) {
    bool onScreen = screenSpace > 0.5;
    float cell = (onScreen ? screen.w : size.y) / ((style > 0.5 ? 0.6 : 2.475) * max(count, 0.5));
    float a = radians(angle);
    float cs = cos(a);
    float sn = sin(a);
    float2 c = (onScreen ? screen.xy + screen.zw * 0.5 : size * 0.5) + offset;
    float2 p = coord - c;
    p = float2(cs * p.x + sn * p.y, -sn * p.x + cs * p.y);
    float2 dims = max(abs(stretch), float2(0.01)) * cell;
    float2 g = p / dims;
    float2 n = floor(g);
    float2 h = hash22(n + seed * 13.17);
    float t = h.x * 6.2831853;
    float2 d = edgeStyle > 0.5 ? (2.0 * h - 1.0) * strength * (onScreen ? screen.w : size.y) * 0.6667 : float2(cos(t), sin(t)) * h.y * strength * (onScreen ? min(screen.z, screen.w) : min(size.x, size.y));
    float2 inside = step(float2(0.0), coord) * step(coord, size);
    float2 q = coord + d;
    if (edgeStyle > 0.5) {
        q = screen.xy + screen.zw - abs(mod(q - screen.xy, 2.0 * screen.zw) - screen.zw);
        q = clamp(q, screen.xy + 0.5, screen.xy + screen.zw - 0.5);
        float2 w = clamp(q + 0.5, 0.0, 1.0) * clamp(size - q + 0.5, 0.0, 1.0);
        return image.eval(clamp(q, float2(0.5), size - 0.5)) * half(w.x * w.y * inside.x * inside.y);
    }
    if (edges > 0.5 && (q.x < 0.0 || q.y < 0.0 || q.x > size.x || q.y > size.y)) return half4(0.0);
    return image.eval(q) * half(inside.x * inside.y);
}
